import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.1lnE8eph.js";const p=JSON.parse('{"title":"Module Boundaries and Lifecycle Enforcement","description":"","frontmatter":{},"headers":[],"relativePath":"specs/005-module-boundaries-lifecycle.md","filePath":"specs/005-module-boundaries-lifecycle.md"}'),c={name:"specs/005-module-boundaries-lifecycle.md"};function n(d,e,s,r,l,u){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="module-boundaries-and-lifecycle-enforcement" tabindex="-1">Module Boundaries and Lifecycle Enforcement <a class="header-anchor" href="#module-boundaries-and-lifecycle-enforcement" aria-label="Permalink to &quot;Module Boundaries and Lifecycle Enforcement&quot;">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Enforce module isolation, shared-state contracts, deterministic teardown and isolated module validation in the Bus Map application. Keep Open-DS as the UI/token source of truth while preserving its React and CSS Modules adaptation.</p><h2 id="architecture-decisions" tabindex="-1">Architecture decisions <a class="header-anchor" href="#architecture-decisions" aria-label="Permalink to &quot;Architecture decisions&quot;">​</a></h2><ul><li>Feature modules must not import or declare dependencies on packages located under <code>modules/</code>.</li><li>Shared lifecycle and editor presentation code belongs in <code>packages/module-runtime</code>, not in a feature module.</li><li>Modules share selection through the typed <code>@busmap/topics</code> contract.</li><li><code>module-map</code> requests an entity dialog through <code>OPEN_ENTITY_DIALOG</code>; the application shell is responsible for creating <code>module-entity-dialog</code>.</li><li>Constructors prepare state only. DOM access, subscriptions and external listeners are established at mount and removed at unmount.</li><li>Open-DS verification is pinned to the exact integration commit <code>30d187b4c833b5348e8c13ad7809a8b16860d404</code>; its source checkout, token version and MCP version must agree.</li><li>Upstream <code>main</code> was checked at <code>a076a4a0cc0747fbc3d67db1e7c84883d6091a24</code>. Its later change is confined to the browser harness, while the app&#39;s locked reference also includes the OD-242 dark-visibility decisions not present on that <code>main</code> tip. Do not silently downgrade those adopted tokens while syncing unrelated upstream changes.</li></ul><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><ul><li><code>yarn test:architecture</code> runs the import-boundary check and isolated map shared-contract tests.</li><li><code>yarn lint</code> runs the architecture tests and workspace TypeScript checks.</li><li><code>yarn build</code> verifies the production application bundle.</li><li>Design-system sync and verification scripts reject an Open-DS checkout whose commit differs from <code>packages/design-system/open-ds.lock.json</code>.</li></ul>',7)])])}const m=o(c,[["render",n]]);export{p as __pageData,m as default};
